    private void btnVentasActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnVentasActionPerformed
        String union = " FROM ordenes o INNER JOIN alimentos a ON a.idalimentos = o.alimentos_idalimentos WHERE o.estadoo = 'Pagado'";

        cnx.entablar("SELECT o.folio, o.fecha_hora, o.mesas_numero AS mesa, o.silla, a.nombrea AS alimento, a.precio" + union
                + " ORDER BY o.fecha_hora DESC", TConsultas, 10, 24, 10, 10, 30, 16);

        String total = cnx.obtenerDato("SELECT SUM(a.precio)" + union);
        double suma = 0;
        if (total != null && !total.isEmpty()) {
            suma = Double.parseDouble(total);
        }
        LTotal.setText("Total de ventas: $" + String.format("%.2f", suma));
    }//GEN-LAST:event_btnVentasActionPerformed

    private void btnOrdenesActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnOrdenesActionPerformed
        LTotal.setText("");
        cnx.entablar("SELECT o.folio, o.fecha_hora, o.mesas_numero AS mesa, o.silla, a.nombrea AS alimento, "
                + "o.estadoo AS estado, o.observaciones, c.nombrec AS cliente, m.nombre AS mesero, k.nombre AS cocinero "
                + "FROM ordenes o "
                + "INNER JOIN alimentos a ON a.idalimentos = o.alimentos_idalimentos "
                + "INNER JOIN clientes c ON c.codigoc = o.clientes_codigoc "
                + "INNER JOIN empleados m ON m.codigo = o.empleados_codigo_mesero "
                + "LEFT JOIN empleados k ON k.codigo = o.empleados_codigo_cocinero "
                + "ORDER BY o.folio DESC", TConsultas, 6, 14, 6, 6, 14, 10, 14, 12, 12, 12);
    }//GEN-LAST:event_btnOrdenesActionPerformed

